            tg3_rrr(1, 2, 2) = tg3_rrr(1, 2, 2) + t_tg3_rrr_011
            tg3_rrr(2, 1, 2) = tg3_rrr(2, 1, 2) + t_tg3_rrr_011
            tg3_rrr(2, 2, 1) = tg3_rrr(2, 2, 1) + t_tg3_rrr_011
            t_tg3_rrr_012 = vr_a*x78
            tg3_rrr(1, 2, 3) = tg3_rrr(1, 2, 3) + t_tg3_rrr_012
            tg3_rrr(1, 3, 2) = tg3_rrr(1, 3, 2) + t_tg3_rrr_012
            tg3_rrr(2, 1, 3) = tg3_rrr(2, 1, 3) + t_tg3_rrr_012
            tg3_rrr(2, 3, 1) = tg3_rrr(2, 3, 1) + t_tg3_rrr_012
            tg3_rrr(3, 1, 2) = tg3_rrr(3, 1, 2) + t_tg3_rrr_012
            tg3_rrr(3, 2, 1) = tg3_rrr(3, 2, 1) + t_tg3_rrr_012
            t_tg3_rrr_022 = vr_a*x80
            tg3_rrr(1, 3, 3) = tg3_rrr(1, 3, 3) + t_tg3_rrr_022
            tg3_rrr(3, 1, 3) = tg3_rrr(3, 1, 3) + t_tg3_rrr_022
            tg3_rrr(3, 3, 1) = tg3_rrr(3, 3, 1) + t_tg3_rrr_022
            tg3_rrr(2, 2, 2) = tg3_rrr(2, 2, 2) + (vr_a*x83)
            t_tg3_rrr_112 = vr_a*x86
            tg3_rrr(2, 2, 3) = tg3_rrr(2, 2, 3) + t_tg3_rrr_112
            tg3_rrr(2, 3, 2) = tg3_rrr(2, 3, 2) + t_tg3_rrr_112
            tg3_rrr(3, 2, 2) = tg3_rrr(3, 2, 2) + t_tg3_rrr_112
            t_tg3_rrr_122 = vr_a*x89
            tg3_rrr(2, 3, 3) = tg3_rrr(2, 3, 3) + t_tg3_rrr_122
            tg3_rrr(3, 2, 3) = tg3_rrr(3, 2, 3) + t_tg3_rrr_122
            tg3_rrr(3, 3, 2) = tg3_rrr(3, 3, 2) + t_tg3_rrr_122
            tg3_rrr(3, 3, 3) = tg3_rrr(3, 3, 3) + (vr_a*x92)
            hvp0_a(1) = hvp0_a(1) + (vr_a*x17)
            hvp0_a(2) = hvp0_a(2) + (vr_a*x20)
            hvp0_a(3) = hvp0_a(3) + (vr_a*x23)
            hvp1_r_a(1, 1) = hvp1_r_a(1, 1) + (vr_a*x32)
            hvp1_r_a(1, 2) = hvp1_r_a(1, 2) + (x93)
            hvp1_r_a(1, 3) = hvp1_r_a(1, 3) + (x94)
            hvp1_r_a(2, 1) = hvp1_r_a(2, 1) + (x93)
            hvp1_r_a(2, 2) = hvp1_r_a(2, 2) + (vr_a*x42)
            hvp1_r_a(2, 3) = hvp1_r_a(2, 3) + (x95)
            hvp1_r_a(3, 1) = hvp1_r_a(3, 1) + (x94)
            hvp1_r_a(3, 2) = hvp1_r_a(3, 2) + (x95)
            hvp1_r_a(3, 3) = hvp1_r_a(3, 3) + (vr_a*x47)
            hvp2_rr_a(1, 1, 1) = hvp2_rr_a(1, 1, 1) + (vr_a*x57)
            hvp2_rr_a(1, 1, 2) = hvp2_rr_a(1, 1, 2) + (x96)
            hvp2_rr_a(1, 1, 3) = hvp2_rr_a(1, 1, 3) + (x97)
            t_hvp2_rr_a_010 = x96
            hvp2_rr_a(1, 2, 1) = hvp2_rr_a(1, 2, 1) + t_hvp2_rr_a_010
            hvp2_rr_a(2, 1, 1) = hvp2_rr_a(2, 1, 1) + t_hvp2_rr_a_010
            t_hvp2_rr_a_011 = x98
            hvp2_rr_a(1, 2, 2) = hvp2_rr_a(1, 2, 2) + t_hvp2_rr_a_011
            hvp2_rr_a(2, 1, 2) = hvp2_rr_a(2, 1, 2) + t_hvp2_rr_a_011
            t_hvp2_rr_a_012 = x99
            hvp2_rr_a(1, 2, 3) = hvp2_rr_a(1, 2, 3) + t_hvp2_rr_a_012
            hvp2_rr_a(2, 1, 3) = hvp2_rr_a(2, 1, 3) + t_hvp2_rr_a_012
            t_hvp2_rr_a_020 = x97
            hvp2_rr_a(1, 3, 1) = hvp2_rr_a(1, 3, 1) + t_hvp2_rr_a_020
            hvp2_rr_a(3, 1, 1) = hvp2_rr_a(3, 1, 1) + t_hvp2_rr_a_020
            t_hvp2_rr_a_021 = x99
            hvp2_rr_a(1, 3, 2) = hvp2_rr_a(1, 3, 2) + t_hvp2_rr_a_021
            hvp2_rr_a(3, 1, 2) = hvp2_rr_a(3, 1, 2) + t_hvp2_rr_a_021
            t_hvp2_rr_a_022 = x100
            hvp2_rr_a(1, 3, 3) = hvp2_rr_a(1, 3, 3) + t_hvp2_rr_a_022
            hvp2_rr_a(3, 1, 3) = hvp2_rr_a(3, 1, 3) + t_hvp2_rr_a_022
            hvp2_rr_a(2, 2, 1) = hvp2_rr_a(2, 2, 1) + (x98)
            hvp2_rr_a(2, 2, 2) = hvp2_rr_a(2, 2, 2) + (vr_a*x82)
            hvp2_rr_a(2, 2, 3) = hvp2_rr_a(2, 2, 3) + (x101)
            t_hvp2_rr_a_120 = x99
            hvp2_rr_a(2, 3, 1) = hvp2_rr_a(2, 3, 1) + t_hvp2_rr_a_120
            hvp2_rr_a(3, 2, 1) = hvp2_rr_a(3, 2, 1) + t_hvp2_rr_a_120
            t_hvp2_rr_a_121 = x101
            hvp2_rr_a(2, 3, 2) = hvp2_rr_a(2, 3, 2) + t_hvp2_rr_a_121
            hvp2_rr_a(3, 2, 2) = hvp2_rr_a(3, 2, 2) + t_hvp2_rr_a_121
            t_hvp2_rr_a_122 = x102
            hvp2_rr_a(2, 3, 3) = hvp2_rr_a(2, 3, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 2, 3) = hvp2_rr_a(3, 2, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 3, 1) = hvp2_rr_a(3, 3, 1) + (x100)
            hvp2_rr_a(3, 3, 2) = hvp2_rr_a(3, 3, 2) + (x102)
            hvp2_rr_a(3, 3, 3) = hvp2_rr_a(3, 3, 3) + (vr_a*x91)
            rh0_a = &
               rh0_a + (v_a(1)*x13 + v_a(1)*x16 + v_a(2)*x18 + v_a(2)*x19 + v_a(3)*x21 + &
               v_a(3)*x22 + vr_a*(x103*x5 + x104*x8))
            rh1_r_a(1) = &
               rh1_r_a(1) + (-v_a(1)*x33 - v_a(2)*x38 - v_a(3)*x41 + vr_a*(d_a(1)*x105 + &
               d_a(1)*x106 + d_a(1)*x108))
            rh1_r_a(2) = &
               rh1_r_a(2) + (-v_a(1)*x38 - v_a(2)*x43 - v_a(3)*x46 + vr_a*(d_a(2)*x105 + &
               d_a(2)*x106 + d_a(2)*x108))
            rh1_r_a(3) = &
               rh1_r_a(3) + (-v_a(1)*x41 - v_a(2)*x46 - v_a(3)*x48 + vr_a*(d_a(3)*x105 + &
               d_a(3)*x106 + d_a(3)*x108))
            rh2_rr_a(1, 1) = &
               rh2_rr_a(1, 1) + (-v_a(1)*x58 - v_a(2)*x64 - v_a(3)*x68 + vr_a*(x109*x59 - x110*x59 &
               + x111*x2 + x112*x26 + x113))
            t_rh2_rr_a_01 = &
               -v_a(1)*x64 - v_a(2)*x75 - v_a(3)*x78 + vr_a*(d_a(2)*x115 + x111*x117 - x116*x117 + &
               x117*x118)
            rh2_rr_a(1, 2) = rh2_rr_a(1, 2) + t_rh2_rr_a_01
            rh2_rr_a(2, 1) = rh2_rr_a(2, 1) + t_rh2_rr_a_01
            t_rh2_rr_a_02 = &
               -v_a(1)*x68 - v_a(2)*x78 - v_a(3)*x80 + vr_a*(d_a(3)*x115 + x111*x119 - x116*x119 + &
               x118*x119)
            rh2_rr_a(1, 3) = rh2_rr_a(1, 3) + t_rh2_rr_a_02
            rh2_rr_a(3, 1) = rh2_rr_a(3, 1) + t_rh2_rr_a_02
            rh2_rr_a(2, 2) = &
               rh2_rr_a(2, 2) + (-v_a(1)*x75 - v_a(2)*x83 - v_a(3)*x86 + vr_a*(x111*x3 + x113 + &
               x114*x3 - x116*x3 + x118*x3))
            t_rh2_rr_a_12 = &
               -v_a(1)*x78 - v_a(2)*x86 - v_a(3)*x89 + vr_a*(x111*x76 + x114*x76 - x116*x76 + &
               x118*x76)
            rh2_rr_a(2, 3) = rh2_rr_a(2, 3) + t_rh2_rr_a_12
            rh2_rr_a(3, 2) = rh2_rr_a(3, 2) + t_rh2_rr_a_12
            rh2_rr_a(3, 3) = &
               rh2_rr_a(3, 3) + (-v_a(1)*x80 - v_a(2)*x89 - v_a(3)*x92 + vr_a*(x111*x4 + x113 + &
               x114*x4 - x116*x4 + x118*x4))
         end block
      end select

   end subroutine cfc_atomic_radius_hvp_eval

   pure module subroutine cfc_pair_radius_hvp_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, &
                                            fade_width, v_a, v_b, vr_a, vr_b, max_deriv, tg0, &
                                            tg1_r, tg2_rr, tg3_rrr, hvp0_a, hvp0_b, hvp1_r_a, &
                                            hvp1_r_b, hvp2_rr_a, hvp2_rr_b, rh0_a, rh0_b, &
                                            rh1_r_a, rh1_r_b, rh2_rr_a, rh2_rr_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Nuclear displacement direction of atom b
      real(wp), intent(in) :: v_b(3)
      !> Radius direction of atom a
      real(wp), intent(in) :: vr_a
      !> Radius direction of atom b
      real(wp), intent(in) :: vr_b
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg0
      !> sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-0 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp0_a(3)
      !> sum_B vr_B d2/(dr_b dR_B) of the order-0 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom b
      real(wp), intent(inout) :: hvp0_b(3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-1 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp1_r_a(3, 3)
      !> sum_B vr_B d2/(dr_b dR_B) of the order-1 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom b
      real(wp), intent(inout) :: hvp1_r_b(3, 3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-2 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp2_rr_a(3, 3, 3)
      !> sum_B vr_B d2/(dr_b dR_B) of the order-2 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom b
      real(wp), intent(inout) :: hvp2_rr_b(3, 3, 3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-0 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh0_a
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_b of the order-0 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh0_b
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-1 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh1_r_a(3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_b of the order-1 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh1_r_b(3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-2 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh2_rr_a(3, 3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_b of the order-2 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh2_rr_b(3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_pair_radius_hvp_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end .or. sg_b >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
               real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
               real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
               real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
               real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + fj1)
               g_a(2) = &
                  fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               sr = (band_end - (sg_b))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_b(0) = fj0
               g_b(1) = a2*fj0 + fj1
               g_b(2) = &
                  (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
                  fp2*fsp2)
               x0 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
               x1 = sqrt(x0)
               x2 = g_a(1)*x1
               x3 = 1.0_wp/(R_a*R_a)
               x4 = 1.0_wp/R_a
               x5 = 1.0_wp/R_b
               x6 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
               x7 = x5*x6
               x8 = -x4*x7 + 1.0_wp
               x9 = (x8*x8*x8*x8)
               x10 = c_par*x9
               x11 = g_b(0)*x10
               x12 = x11*x3
               x13 = (x8*x8*x8)
               x14 = (d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))
               x15 = sqrt(x14)
               x16 = g_b(1)*x15
               x17 = 1.0_wp/(R_b*R_b)
               x18 = g_a(0)*x10
               x19 = x17*x18
               x20 = c_par*g_a(0)*g_b(0)
               x21 = x13*x20
               x22 = 4.0_wp*x21
               x23 = x17*x22*x4
               x24 = 1.0_wp/(R_b*R_b*R_b)
               x25 = (x8*x8)
               x26 = d_b(1)*x24
               x27 = c_par*x13
               x28 = 4.0_wp*x27
               x29 = g_a(0)*x28
               x30 = x29*x4
               x31 = x26*x30
               x32 = 1.0_wp/x1
               x33 = g_a(1)*x32
               x34 = x17*x6
               x35 = g_b(0)*x28
               x36 = x3*x34*x35
               x37 = &
